sys_script_include.script:
var SchemaUtil = Class.create();
SchemaUtil.prototype = {
    initialize: function() {
        this.registry = new SchemaRegistry(); // centralized schema store
    },

    /**
     * Retrieves the schema from the registry and maps the payload into normalized records.
     * @param {string} schemaKey - e.g. 'application_data'
     * @param {object} payload - raw JSON response from Panorama
     * @returns {object} { records: [...] }
	 * 
     * The below function uses the schema map to determine which keys and values we extract from the JSON received from the REST request. To add additional values, add them to the SchemaRegistry. To insert these values, ensure the table columns existing on corresponding staging and target tables in the Transform record.
     *
     *
     */
    parseResponse: function(schemaKey, payload) {
        var schema = this.registry.getSchema(schemaKey);
        if (!schema) {
            gs.error("[SchemaUtil] No schema found for key: " + schemaKey);
            return {
                records: []
            };
        }

        var rawEntries = this._extractEntries(payload);
        var map = schema.map;
        var results = [];

        for (var i = 0; i < rawEntries.length; i++) {
            var entry = rawEntries[i];
            var record = {};

            for (var targetKey in map) {
                if (!map.hasOwnProperty(targetKey)) continue;
                var path = map[targetKey];
                var value = this._resolvePath(entry, path);
                record[targetKey] = this._normalizeValue(value);
            }

            results.push(record);
        }

        return {
            records: results
        };
    },

    /**
     * Pulls the relevant node in the Panorama response (e.g. result.entry[])
     */
    _extractEntries: function(payload) {
        if (!payload) return [];
        if (payload.result && payload.result.entry)
            return Array.isArray(payload.result.entry) ? payload.result.entry : [payload.result.entry];
        return [];
    },

    _dedupeByKey: function(records, key) {
        var seen = {};
        return records.filter(function(rec) {
            var val = rec[key];
            if (!val) return true; // keep if key not defined
            if (seen[val]) return false; // drop dup
            seen[val] = true;
            return true;
        });
    },

    _resolvePath: function(obj, path) {
        if (!obj || !path) return null;
        var parts = path.split(".");
        var current = obj;

        for (var i = 0; i < parts.length; i++) {
            if (current == null) return null;
            current = current[parts[i]];
        }

        return current;
    },
    /**
    Panorama uses {member : []} when multiple values are present for a property so we must normalize these values into strings before we pass them into the Import Set Import Multiple endpoint for insertion.

	* Review the JSON response from the relevant endpoint as additional handling may be required if the structure of the data is not flat. For example, the normalizeValue function serves to stringify multiple values nested inside the 'default.port.member' and 'list.member' from Panorama application profiles and url categories, respectively.
    **/
    _normalizeValue: function(value) {
        if (value && typeof value === "object" && value.member) {
            var arr = Array.isArray(value.member) ? value.member : [value.member];
            return arr.join(",");
        }
        if (Array.isArray(value)) return value.join(",");
        return value || null;
    },

    type: 'SchemaUtil'
};
